class Solution {
  public double findMaxAverage(int[] nums, int k) {
    double lo = -1e4, hi = 1e4;
    // binary search the average: is there a subarray of length >= k with average >= mid?
    while (hi - lo > 1e-6) {
      double mid = (lo + hi) / 2;
      if (possible(nums, k, mid)) lo = mid;
      else hi = mid;
    }
    return lo;
  }

  private boolean possible(int[] nums, int k, double avg) {
    double sum = 0, prev = 0, minPrev = 0;
    for (int i = 0; i < k; i++) sum += nums[i] - avg;
    if (sum >= 0) return true;
    for (int i = k; i < nums.length; i++) {
      sum += nums[i] - avg;
      prev += nums[i - k] - avg;
      minPrev = Math.min(minPrev, prev);
      if (sum - minPrev >= 0) return true;
    }
    return false;
  }
}
